 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    by_row = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
    axis = max(by_row, key=lambda r: len(by_row[r]))
    axis_cols = by_row[axis]
    left, right = min(axis_cols), max(axis_cols)
    for c in range(left + 1, right):
        if out[axis][c] == 0:
            out[axis][c] = 3
