        if r < axis:
            for rr in range(r + 1, axis):
                if out[rr][c] == 0:
                    out[rr][c] = 3
        elif r > axis:
            for rr in range(axis + 1, r):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    return out

